import sys,time
INF=100000000
MATE=100000
VALUE={'p':100,'n':320,'b':335,'r':500,'q':900,'k':20000}
PROM={1:'n',2:'b',3:'r',4:'q'}


def attacked(p,sq,side):
    if sq<0 or sq>=64:return False
    b=p.board;r,f=divmod(sq,8)
    pawn='P' if side==0 else 'p'
    pr=r-1 if side==0 else r+1
    if 0<=pr<8:
        for df in (-1,1):
            ff=f+df
            if 0<=ff<8 and b[pr*8+ff]==pawn:return True
    knight='N' if side==0 else 'n'
    for dr,df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
        rr,ff=r+dr,f+df
        if 0<=rr<8 and 0<=ff<8 and b[rr*8+ff]==knight:return True
    king='K' if side==0 else 'k'
    for dr in (-1,0,1):
        for df in (-1,0,1):
            if dr or df:
                rr,ff=r+dr,f+df
                if 0<=rr<8 and 0<=ff<8 and b[rr*8+ff]==king:return True
    rays=((1,0,'rq'),(-1,0,'rq'),(0,1,'rq'),(0,-1,'rq'),(1,1,'bq'),(1,-1,'bq'),(-1,1,'bq'),(-1,-1,'bq'))
    for dr,df,chars in rays:
        rr,ff=r+dr,f+df
        while 0<=rr<8 and 0<=ff<8:
            x=b[rr*8+ff]
            if x!='.':
                if x.isupper()==(side==0) and x.lower() in chars:return True
                break
            rr+=dr;ff+=df
    return False


def king_square(p,side):
    k='K' if side==0 else 'k'
    for i,x in enumerate(p.board):
        if x==k:return i
    return -1


class Position:
    def __init__(self,board,side,rights,ep,half,full):
        self.board=board
        self.side=side
        self.rights=rights
        self.ep=ep
        self.half=half
        self.full=full

    @classmethod
    def start(cls):
        return cls.fen('rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1')

    @classmethod
    def fen(cls,text):
        fields=text.split()
        if len(fields)<6:fields='rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1'.split()
        board=['.']*64
        for row,line in enumerate(fields[0].split('/')):
            sq=(7-row)*8
            for ch in line:
                if ch.isdigit():sq+=int(ch)
                else:
                    if 0<=sq<64:board[sq]=ch
                    sq+=1
        rights=0
        for i,ch in enumerate('KQkq'):
            if ch in fields[2]:rights|=1<<i
        ep=-1
        if fields[3]!='-' and len(fields[3])==2:
            ep=ord(fields[3][0])-97+8*(ord(fields[3][1])-49)
        try:half=int(fields[4]);full=int(fields[5])
        except ValueError:half=0;full=1
        return cls(board,0 if fields[1]=='w' else 1,rights,ep,half,full)


def move_code(a,z,promotion=0,flags=0):
    return a|(z<<6)|(promotion<<12)|(flags<<16)


def pseudo(p,capture_only=False):
    b=p.board;white=p.side==0;out=[]
    def add(a,z,pr=0,flags=0,cap=False):
        if capture_only and not (cap or pr):return
        out.append(move_code(a,z,pr,flags))
    for a,pc in enumerate(b):
        if pc=='.' or pc.isupper()!=white:continue
        r,f=divmod(a,8);kind=pc.lower()
        if kind=='p':
            step=8 if white else -8
            z=a+step
            promotion=0<=z<64 and z//8==(7 if white else 0)
            if 0<=z<64 and b[z]=='.':
                if promotion:
                    for pr in (4,3,2,1):add(a,z,pr)
                else:add(a,z)
                if not capture_only and r==(1 if white else 6) and b[a+2*step]=='.':add(a,a+2*step)
            for df in (-1,1):
                ff=f+df
                if not 0<=ff<8:continue
                z=a+step+df
                if not 0<=z<64:continue
                target=b[z]
                enemy=target!='.' and target.isupper()!=white and target.lower()!='k'
                if enemy:
                    if z//8==(7 if white else 0):
                        for pr in (4,3,2,1):add(a,z,pr,0,True)
                    else:add(a,z,0,0,True)
                elif z==p.ep and target=='.':
                    cs=z-8 if white else z+8
                    if 0<=cs<64 and b[cs]==('p' if white else 'P'):add(a,z,0,2,True)
        elif kind=='n':
            for dr,df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
                rr,ff=r+dr,f+df
                if 0<=rr<8 and 0<=ff<8:
                    z=rr*8+ff;x=b[z]
                    if x=='.' or (x.isupper()!=white and x.lower()!='k'):add(a,z,0,0,x!='.')
        elif kind in 'brq':
            dirs=[]
            if kind in 'bq':dirs.extend(((1,1),(1,-1),(-1,1),(-1,-1)))
            if kind in 'rq':dirs.extend(((1,0),(-1,0),(0,1),(0,-1)))
            for dr,df in dirs:
                rr,ff=r+dr,f+df
                while 0<=rr<8 and 0<=ff<8:
                    z=rr*8+ff;x=b[z]
                    if x=='.':add(a,z)
                    else:
                        if x.isupper()!=white and x.lower()!='k':add(a,z,0,0,True)
                        break
                    rr+=dr;ff+=df
        else:
            for dr in (-1,0,1):
                for df in (-1,0,1):
                    if dr or df:
                        rr,ff=r+dr,f+df
                        if 0<=rr<8 and 0<=ff<8:
                            z=rr*8+ff;x=b[z]
                            if x=='.' or (x.isupper()!=white and x.lower()!='k'):add(a,z,0,0,x!='.')
            if not capture_only and a==(4 if white else 60) and not attacked(p,a,p.side^1):
                if white and p.rights&1 and b[5]==b[6]=='.' and b[7]=='R' and not attacked(p,5,1) and not attacked(p,6,1):add(a,6,0,1)
                if white and p.rights&2 and b[1]==b[2]==b[3]=='.' and b[0]=='R' and not attacked(p,3,1) and not attacked(p,2,1):add(a,2,0,1)
                if not white and p.rights&4 and b[61]==b[62]=='.' and b[63]=='r' and not attacked(p,61,0) and not attacked(p,62,0):add(a,62,0,1)
                if not white and p.rights&8 and b[57]==b[58]==b[59]=='.' and b[56]=='r' and not attacked(p,59,0) and not attacked(p,58,0):add(a,58,0,1)
    return out


def make_move(p,m):
    a=m&63;z=(m>>6)&63;pr=(m>>12)&15;flags=m>>16
    b=p.board[:];pc=b[a];captured=b[z]
    b[a]='.'
    if flags&2:
        cs=z-8 if pc.isupper() else z+8
        b[cs]='.';captured='p'
    b[z]=pc
    if flags&1:
        if z==6:b[5]=b[7];b[7]='.'
        elif z==2:b[3]=b[0];b[0]='.'
        elif z==62:b[61]=b[63];b[63]='.'
        elif z==58:b[59]=b[56];b[56]='.'
    if pr:b[z]=('NBRQ' if pc.isupper() else 'nbrq')[pr-1]
    rights=p.rights
    if pc=='K':rights&=12
    elif pc=='k':rights&=3
    if pc=='R' and a==0:rights&=~2
    if pc=='R' and a==7:rights&=~1
    if pc=='r' and a==56:rights&=~8
    if pc=='r' and a==63:rights&=~4
    if captured=='R' and z==0:rights&=~2
    if captured=='R' and z==7:rights&=~1
    if captured=='r' and z==56:rights&=~8
    if captured=='r' and z==63:rights&=~4
    ep=(a+z)//2 if pc.lower()=='p' and abs(z-a)==16 else -1
    half=0 if pc.lower()=='p' or captured!='.' else p.half+1
    full=p.full+(1 if p.side else 0)
    return Position(b,p.side^1,rights,ep,half,full)


def legal_moves(p,capture_only=False):
    result=[];side=p.side
    for m in pseudo(p,capture_only):
        q=make_move(p,m);ks=king_square(q,side)
        if ks>=0 and not attacked(q,ks,side^1):result.append(m)
    return result


def uci_name(m):
    a=m&63;z=(m>>6)&63;pr=(m>>12)&15
    result='abcdefgh'[a&7]+str(a//8+1)+'abcdefgh'[z&7]+str(z//8+1)
    return result+(PROM[pr] if pr else '')


class Engine:
    def __init__(self):
        self.pos=Position.start();self.tt={};self.history={};self.killers={};self.nodes=0;self.deadline=0.0

    def evaluate(self,p):
        score=0;phase=0;white_pawns=[0]*8;black_pawns=[0]*8;bishops=[0,0];pawn_count=0
        for x in p.board:
            if x!='.' and x.lower() in 'nbrq':phase+=VALUE[x.lower()]
        for s,x in enumerate(p.board):
            if x=='.':continue
            kind=x.lower();sg=1 if x.isupper() else -1;r,f=divmod(s,8);rank=r if sg==1 else 7-r
            center=max(0,7-abs(2*f-7)-abs(2*rank-7));score+=sg*VALUE[kind]
            if kind=='p':
                pawn_count+=1
                (white_pawns if sg==1 else black_pawns)[f]+=1
                score+=sg*(rank*8+center*2)
                passed=True
                for rr in (range(r+1,8) if sg==1 else range(r-1,-1,-1)):
                    for ff in (f-1,f,f+1):
                        if 0<=ff<8 and p.board[rr*8+ff]==('p' if sg==1 else 'P'):passed=False
                if passed:score+=sg*(18+rank*9)
            elif kind=='n':score+=sg*center*11
            elif kind=='b':score+=sg*center*5;bishops[0 if sg==1 else 1]+=1
            elif kind=='r':
                score+=sg*(rank*3+(10 if (white_pawns if sg==1 else black_pawns)[f]==0 else 0))
            elif kind=='q':score+=sg*center*2
            else:
                score+=sg*((-center*4) if phase>2300 else center*9)
        if bishops[0]>=2:score+=32
        if bishops[1]>=2:score-=32
        for n in white_pawns:score-=max(0,n-1)*11
        for n in black_pawns:score+=max(0,n-1)*11
        for f,n in enumerate(white_pawns):
            if n and (f==0 or white_pawns[f-1]==0) and (f==7 or white_pawns[f+1]==0):score-=9*n
        for f,n in enumerate(black_pawns):
            if n and (f==0 or black_pawns[f-1]==0) and (f==7 or black_pawns[f+1]==0):score+=9*n
        if pawn_count==0 and phase in (0,320,335):return 0
        return score if p.side==0 else -score

    def poll(self):
        self.nodes+=1
        if (self.nodes&31)==0 and time.perf_counter()>=self.deadline:raise TimeoutError

    def move_score(self,p,m,ttmove,ply):
        a=m&63;z=(m>>6)&63;pr=(m>>12)&15;flags=m>>16;sc=0
        if m==ttmove:sc+=10000000
        target=p.board[z]
        if flags&2:target='p'
        if target!='.':sc+=1000000+VALUE[target.lower()]*12-VALUE[p.board[a].lower()]
        if pr:sc+=800000+pr*10000
        if self.killers.get(ply)==m:sc+=50000
        sc+=self.history.get((p.side,a,z),0)
        rr,ff=divmod(z,8);sc+=max(0,7-abs(2*ff-7)-abs(2*rr-7))*15
        if p.board[a].lower()=='p' and abs(z-a)==16:sc+=25
        return sc

    def quiescence(self,p,alpha,beta,ply):
        self.poll();checked=attacked(p,king_square(p,p.side),p.side^1)
        if checked:
            moves=legal_moves(p)
            if not moves:return -MATE+ply
            if ply>=10:return self.evaluate(p)
        else:
            stand=self.evaluate(p)
            if stand>=beta:return stand
            if stand>alpha:alpha=stand
            if ply>=10:return stand
            moves=legal_moves(p,True)
            if not moves:return alpha
        moves.sort(key=lambda x:self.move_score(p,x,-1,ply),reverse=True)
        for m in moves:
            value=-self.quiescence(make_move(p,m),-beta,-alpha,ply+1)
            if value>=beta:return value
            if value>alpha:alpha=value
        return alpha

    def search(self,p,depth,alpha,beta,ply):
        self.poll()
        if depth<=0:return self.quiescence(p,alpha,beta,ply)
        key=(tuple(p.board),p.side,p.rights,p.ep);original=alpha;entry=self.tt.get(key);ttmove=-1
        if entry:
            ttdepth,value,bound,ttmove=entry
            if ttdepth>=depth:
                if bound==0:return value
                if bound==1:alpha=max(alpha,value)
                else:beta=min(beta,value)
                if alpha>=beta:return value
        moves=legal_moves(p)
        if not moves:
            return -MATE+ply if attacked(p,king_square(p,p.side),p.side^1) else 0
        moves.sort(key=lambda x:self.move_score(p,x,ttmove,ply),reverse=True)
        best=-INF;bestmove=moves[0];beta_original=beta
        for m in moves:
            q=make_move(p,m);next_depth=depth-1
            if next_depth and attacked(q,king_square(q,q.side),q.side^1):next_depth+=1
            value=-self.search(q,next_depth,-beta,-alpha,ply+1)
            if value>best:best=value;bestmove=m
            if value>alpha:alpha=value
            if alpha>=beta:
                a=m&63;z=(m>>6)&63
                if p.board[a].lower()!='p' and p.board[z]=='.' and not (m>>12)&15:
                    self.killers[ply]=m
                    hkey=(p.side,a,z);self.history[hkey]=min(20000,self.history.get(hkey,0)+depth*depth)
                break
        bound=2 if best<=original else 1 if best>=beta_original else 0
        self.tt[key]=(depth,best,bound,bestmove)
        if len(self.tt)>140000:self.tt.clear()
        return best

    def root_search(self,p,moves,depth):
        ordered=moves[:]
        ordered.sort(key=lambda x:self.move_score(p,x,-1,0),reverse=True)
        best=-INF;bestmove=ordered[0]
        for m in ordered:
            self.poll()
            value=-self.search(make_move(p,m),depth-1,-INF,INF,1)
            if value>best:best=value;bestmove=m
        return best,bestmove

    def think(self,millis):
        moves=legal_moves(self.pos)
        if not moves:return '0000'
        moves.sort(key=lambda x:self.move_score(self.pos,x,-1,0),reverse=True)
        best=moves[0]
        if len(moves)==1 or millis<=12:return uci_name(best)
        self.nodes=0
        self.deadline=time.perf_counter()+max(0.002,millis*0.86/1000.0)
        for depth in range(1,40):
            try:
                value,m=self.root_search(self.pos,moves,depth)
            except TimeoutError:break
            best=m
            if abs(value)>=MATE-1000:break
        return uci_name(best)

    def set_position(self,args):
        if len(args)>=2 and args[1]=='startpos':
            p=Position.start();index=2
        elif len(args)>=8 and args[1]=='fen':
            p=Position.fen(' '.join(args[2:8]));index=8
        else:return
        if index<len(args) and args[index]=='moves':
            for text in args[index+1:]:
                chosen=None
                for m in legal_moves(p):
                    if uci_name(m)==text:chosen=m;break
                if chosen is None:break
                p=make_move(p,chosen)
        self.pos=p


def main():
    engine=Engine()
    for line in sys.stdin:
        args=line.strip().split()
        if not args:continue
        command=args[0]
        if command=='uci':
            print('id name CleanRoomPython')
            print('id author Codex')
            print('uciok');sys.stdout.flush()
        elif command=='isready':
            print('readyok');sys.stdout.flush()
        elif command=='ucinewgame':
            engine.tt.clear();engine.history.clear();engine.killers.clear();engine.pos=Position.start()
        elif command=='position':
            engine.set_position(args)
        elif command=='go':
            milliseconds=1000
            if 'movetime' in args:
                try:milliseconds=max(1,int(args[args.index('movetime')+1]))
                except (ValueError,IndexError):milliseconds=1000
            print('bestmove '+engine.think(milliseconds));sys.stdout.flush()
        elif command=='quit':
            break


if __name__=='__main__':main()
